import json

raw_file = 'src/ptable/data/drafts/Palladium_raw.json'
out_file = 'src/ptable/data/drafts/Palladium.json'

with open(raw_file, 'r', encoding='utf-8') as f:
    data = json.load(f)

extract_html = """<p><b><a href="/school1/ptable/element/Pd" class="wiki-link" title="Palladium (Pd)">Palladium</a></b> is a brilliant, silvery-white metal that plays a massive hidden role in our daily lives. Discovered in 1803 by English chemist William Hyde Wollaston and named after the asteroid Pallas, it sits right next to platinum and shares many of its prized qualities. It doesn't tarnish easily, and uniquely, it can soak up 900 times its own volume in hydrogen gas! Palladium is a true superhero of modern industry, mostly famous for its use in cars to clean up toxic exhaust fumes. While major global supplies come from South Africa and Russia, India has recently tapped into this precious resource. Geological surveys have found traces of palladium-bearing platinum group elements in ancient Precambrian rocks in states like Odisha, Tamil Nadu, and Karnataka. In fact, Odisha even started a pilot project in 2026 to extract these valuable metals locally. Whether it's shining in fine "white gold" jewelry or making our air cleaner, palladium is an incredibly valuable element.</p>"""

history = """<p>In 1802, English chemist William Hyde Wollaston noticed a mysterious new noble metal in his lab. He named it <b>palladium</b> in August of that year, inspired by the recently discovered asteroid "Pallas" (which astronomers thought was a planet at the time). Wollaston managed to purify some of the metal from crude platinum ore found in South America and famously sold it anonymously in a small London shop in 1803. This sparked drama when another scientist, Richard Chenevix, wrongly claimed it was just a fake alloy of platinum and mercury. Wollaston even offered a £20 reward to anyone who could artificially create it—a prize no one could claim because palladium was indeed a brand-new element! He finally revealed himself as its true discoverer in 1805.</p><p>Historically, palladium chloride was actually prescribed to treat tuberculosis, though its side effects soon led doctors to find better medicines. By the 20th and 21st centuries, the metal became incredibly valuable. As countries worldwide—including India, with its strict BS-VI emission standards—demanded cleaner cars, the need for palladium in catalytic converters skyrocketed. Because most of it comes from Russia and South Africa, political events and supply delays have historically caused wild price spikes. To secure their own supplies, countries like India have begun exploring local deposits. Geological surveys have identified potential platinum group element reserves in ancient rock formations, like the Baula-Nuasahi and Sukinda areas in Odisha, and the Sittampundi complex in Tamil Nadu, marking an exciting new chapter in India's hunt for this rare metal.</p>"""

applications = """<p>Today, the biggest job for <b>palladium</b> is cleaning up our environment. It is the key ingredient in the catalytic converters of most gasoline-powered cars, turning toxic exhaust gases into safer substances. In India, the push for cleaner air and the adoption of strict BS-VI emission norms has made palladium more critical than ever. But its talents don't stop there! Because it can absorb huge amounts of hydrogen, it is being researched for hydrogen fuel cells, the clean energy of the future.</p><p>Beyond saving the planet, palladium is also highly valued in electronics, dentistry, and even professional concert flutes. In the world of fashion and culture, palladium is a shining star. It is frequently mixed with gold to create gorgeous "white gold" jewelry, offering a lighter, tarnish-resistant alternative to platinum that has become increasingly popular with Indian consumers and investors alike. As a highly precious commodity, it is one of only four metals (alongside gold, silver, and platinum) to have its own official currency codes. As demand grows, local efforts like Odisha's pilot project to extract platinum group metals from native chromite ores highlight just how important palladium has become to modern technology and the economy.</p>"""

characteristics = """<p>Palladium doesn't react with oxygen at room temperature, which means it doesn't tarnish in the air, keeping its beautiful silver-white shine. If you heat it up to a scorching 800 °C, it will finally start to form a thin brownish layer on the surface, but otherwise, it stays brilliantly clean. One of its most amazing features is that it can act as a superconductor (carrying electricity with zero resistance) when cooled to incredibly low temperatures and bombarded with alpha particles.</p>"""

isotopes = """<p>In nature, <b>palladium</b> is made up of six stable, unchanging forms called isotopes. However, scientists have discovered dozens of other radioactive versions (radioisotopes) of the metal. The longest-lasting of these, Palladium-107, can survive for 6.5 million years and can even be found in tiny trace amounts in nature! Most of the other radioactive isotopes vanish incredibly quickly, breaking down into neighboring elements like rhodium or silver in just a matter of hours or days. Interestingly, studying these specific isotopes in ancient meteorites helps astronomers understand how our early Solar System and its rocky planets formed billions of years ago. Palladium-107 is also slowly created inside modern nuclear reactors, although it's considered one of the safer, more benign byproducts.</p>"""

occurrence = """<p>Mining for <b>palladium</b> is a massive global effort, with total production reaching over 210,000 kilograms in 2022! Most of the world's supply currently comes from deep nickel and copper mines in Russia and South Africa, with smaller amounts sourced from Canada, the United States, and Zimbabwe. It's incredibly rare to find free-floating chunks of pure palladium; instead, it usually hides out naturally blended with gold and platinum in riverbeds and deep rock formations.</p><p>Interestingly, India is beginning to make its own mark on the palladium map. Geological experts have identified promising reserves of platinum group metals—which include palladium—in ancient, billion-year-old rock formations across the country. In states like Odisha (notably the Baula-Nuasahi and Sukinda areas), Tamil Nadu (the Sittampundi complex), and parts of Karnataka, the metal has been traced in underground chromite ore bodies. Recognizing this hidden potential, India is even exploring new ways to mine and process these local reserves, reducing reliance on global superpowers. Though theoretically, scientists could also extract palladium from spent nuclear fuel, the process is too complex and expensive to be used today, making earthly mining efforts in places like South Africa, Russia, and potentially India, our best source.</p>"""

data["extract_html"] = extract_html
if "sections" not in data:
    data["sections"] = {}
data["sections"]["History"] = history
data["sections"]["Applications"] = applications
data["sections"]["Characteristics"] = characteristics
data["sections"]["Isotopes"] = isotopes
data["sections"]["Occurrence"] = occurrence

with open(out_file, 'w', encoding='utf-8') as f:
    json.dump(data, f, indent=4)
print("Palladium rewritten successfully!")
